def send_message_to_user(self, user, message, event, method="say"):
        if method == "say":
            self.say(user.name + ", " + lowercase_first_letter(message))
        elif method == "whisper":
            self.whisper(user, message)
        elif method == "me":
            self.me(message)
        elif method == "reply":
            if event.type in ["action", "pubmsg"]:
                self.say(message)
            elif event.type == "whisper":
                self.whisper(user, message)
        else:
            log.warning("Unknown send_message method: %s", method)

def whisper(bot, message, **rest):
        if not message:
            return False

        msg_args = message.split(" ")
        if len(msg_args) > 1:
            username = msg_args[0]
            rest = " ".join(msg_args[1:])
            bot.whisper_login(username, rest)

